"""Dependency-free contracts for GitHub JVM diagnostic coverage."""
import json
import os
from pathlib import Path
import re
import shlex
import shutil
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]
JOBS = {
    'pr-verify.yml': ['formatting-and-quick-compile', 'lmdb-unit-tests', 'unit-tests', 'integration-tests', 'slow-tests', 'e2e'],
    'main-status.yml': ['build'],
    'develop-status.yml': ['build'],
    'lmdb-mapped-pages.yml': ['mapped-pages'],
    'lmdb-bulk-load-launcher-windows.yml': ['launcher'],
    'lmdb-qemu-durability.yml': ['lmdb-qemu-durability'],
    'sparql-generated-sources.yml': ['generated-source-replay'],
}

class CiJvmDiagnosticsTest(unittest.TestCase):
    def configure(self, root, prior='-Dkeep.me=preserved'):
        setup = ROOT / '.github/actions/jvm-diagnostics/setup.js'
        self.assertTrue(setup.is_file(), 'shared diagnostic setup must exist')
        environment = {'RUNNER_TEMP': str(root / 'runner temp'), 'GITHUB_ENV': str(root / 'github-env'),
                       'JAVA_TOOL_OPTIONS': prior}
        environment['RUNNER_TEMP'] = str(root / 'runner temp')
        Path(environment['RUNNER_TEMP']).mkdir(exist_ok=True)
        code = 'const result = require(process.argv[1]).configure(JSON.parse(process.argv[2])); console.log(JSON.stringify(result));'
        result = subprocess.run([shutil.which('node') or 'node', '-e', code, str(setup), json.dumps(environment)],
                                check=True, capture_output=True, text=True)
        return json.loads(result.stdout), Path(environment['GITHUB_ENV']).read_text()

    def test_setup_preserves_options_and_writes_only_diagnostic_flags(self):
        with tempfile.TemporaryDirectory() as temp:
            result, exported = self.configure(Path(temp))
            self.assertTrue(Path(result['directory']).is_dir())
            self.assertIn('-Dkeep.me=preserved', result['javaToolOptions'])
            diagnostic = shlex.split(result['diagnosticOptions'])
            self.assertIn('-XX:+HeapDumpOnOutOfMemoryError', diagnostic)
            self.assertIn('-XX:HeapDumpGzipLevel=1', diagnostic)
            self.assertIn('-XX:HeapDumpPath=' + result['directory'].replace('\\', '/') + '/java_pid%p.hprof.gz', diagnostic)
            self.assertIn('-XX:ErrorFile=' + result['directory'].replace('\\', '/') + '/hs_err_pid%p.log', diagnostic)
            self.assertFalse(any(option.startswith(('-Xmx', '-Xms', '-javaagent', '-XX:+ExitOn', '-XX:+CrashOn')) for option in diagnostic))
            for variable in ('JAVA_TOOL_OPTIONS', 'RDF4J_CI_JVM_DIAGNOSTIC_OPTIONS', 'RDF4J_JVM_DIAGNOSTICS_DIR'):
                self.assertIn(variable + '<<', exported)

    def test_each_setup_uses_a_distinct_directory(self):
        with tempfile.TemporaryDirectory() as temp:
            first, _ = self.configure(Path(temp), '')
            second, _ = self.configure(Path(temp), '')
            self.assertNotEqual(first['directory'], second['directory'])

    def test_all_jvm_test_jobs_enable_and_always_upload(self):
        for workflow, jobs in JOBS.items():
            text = (ROOT / '.github/workflows' / workflow).read_text()
            for job in jobs:
                with self.subTest(workflow=workflow, job=job):
                    block = re.search(r'^  ' + re.escape(job) + r':\n(.*?)(?=^  [a-zA-Z][\w-]*:|\Z)', text, re.M | re.S).group(1)
                    self.assertIn('uses: ./.github/actions/jvm-diagnostics', block)
                    self.assertIn('mode: setup', block)
                    self.assertIn('mode: upload', block)
                    self.assertRegex(block, r'if: \$\{\{ always\(\) \}\}\n\s+uses: \./\.github/actions/jvm-diagnostics')
                    self.assertIn('strategy.job-index', block, 'matrix artifact names must be unique')

    def test_upload_covers_caught_oom_raw_heap_and_native_logs(self):
        action = (ROOT / '.github/actions/jvm-diagnostics/action.yml').read_text()
        self.assertIn('retention-days: 7', action)
        self.assertIn('if-no-files-found: ignore', action)
        self.assertIn('*.hprof', action)
        self.assertIn('*.hprof.gz', action)
        self.assertIn('hs_err_pid*.log', action)
        self.assertIn("env.RDF4J_JVM_DIAGNOSTICS_DIR != ''", action, 'never glob an empty absolute root')
        self.assertIn('extra-paths', action)
        qemu = (ROOT / '.github/workflows/lmdb-qemu-durability.yml').read_text()
        self.assertIn('/campaigns/**/results/jvm-diagnostics/**', qemu)

    def test_sanitized_child_jvms_restore_only_ci_diagnostics(self):
        names = ['LmdbDecodedNativeAdjacencyPromotionTest.java', 'LmdbNativeKernelSubplanScopeTest.java', 'LmdbBulkLoadTest.java']
        for name in names:
            paths = list(ROOT.rglob(name))
            self.assertEqual(len(paths), 1)
            text = paths[0].read_text()
            self.assertIn('System.getenv("RDF4J_CI_JVM_DIAGNOSTIC_OPTIONS")', text)
            self.assertIn('environment().put("JAVA_TOOL_OPTIONS", ciDiagnostics)', text)
            self.assertIn('ciDiagnostics != null && !ciDiagnostics.isBlank()', text)

    def test_docker_override_persists_dumps_outside_disposable_volumes(self):
        override = (ROOT / 'docker/docker-compose.jvm-diagnostics.yml').read_text()
        self.assertIn('JAVA_TOOL_OPTIONS', override)
        self.assertIn('RDF4J_JVM_DIAGNOSTICS_DIR', override)
        self.assertIn('type: bind', override)
        self.assertIn('/rdf4j-jvm-diagnostics', override)
        for file in ['docker/run.sh', 'e2e/run.sh', 'e2e/run-http-compression.sh']:
            text = (ROOT / file).read_text()
            self.assertIn('ci-jvm-diagnostics.sh', text)
            self.assertNotIn('docker compose ', text, 'all lifecycle calls must use the same diagnostics override')

    def test_explicit_native_error_paths_use_ci_output_when_enabled(self):
        for name in ['LmdbIndexRebuildGrowthTest.java', 'LmdbPreparedBulkStoreTest.java',
                     'TripleStoreInitializationTest.java', 'LmdbDataFileHeaderBufferTest.java']:
            source = next(ROOT.rglob(name)).read_text()
            self.assertIn('System.getenv("RDF4J_JVM_DIAGNOSTICS_DIR")', source)
            self.assertIn('diagnosticsDirectory.resolve(', source)

    def test_container_restarts_use_fresh_heap_directories(self):
        for name in ['entrypoint-tomcat.sh', 'entrypoint-jetty.sh']:
            text = (ROOT / 'docker' / name).read_text()
            self.assertIn('RDF4J_CONTAINER_JVM_DIAGNOSTICS_ROOT', text)
            self.assertIn('mktemp -d', text)
            self.assertIn('java_pid%p.hprof.gz', text)

    def test_upload_prepares_container_owned_files_without_following_symlinks(self):
        prepare = ROOT / '.github/actions/jvm-diagnostics/prepare-upload.js'
        self.assertTrue(prepare.is_file())
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            owned = root / 'root-owned.hprof'
            owned.write_text('synthetic dump')
            owned.chmod(0)
            outside = root / 'outside.txt'
            outside.write_text('must not change')
            link = root / 'java_pid999.hprof'
            link.symlink_to(outside)
            code = '''const fs = require('node:fs');
const calls = [];
require(process.argv[1]).prepare(process.argv[2], (file, mode) => {
 calls.push(file); fs.chmodSync(file, mode === 'a+r' ? 0o644 : 0o755);
});
console.log(JSON.stringify(calls));'''
            result = subprocess.run(['node', '-e', code, str(prepare), str(root)],
                                    check=True, capture_output=True, text=True)
            self.assertEqual(json.loads(result.stdout), [str(owned)])
            self.assertEqual(outside.read_text(), 'must not change')
            self.assertEqual(owned.read_text(), 'synthetic dump')

    def test_docker_wrapper_does_not_change_local_options(self):
        helper = ROOT / 'docker/ci-jvm-diagnostics.sh'
        self.assertTrue(helper.is_file())
        script = 'source "$1"; docker() { printf "%s\\n" "$@"; }; rdf4j_ci_docker_compose ps -q rdf4j'
        environment = dict(os.environ)
        environment.pop('RDF4J_JVM_DIAGNOSTICS_DIR', None)
        actual = subprocess.run(['bash', '-c', script, 'test', str(helper)], env=environment,
                                capture_output=True, text=True, check=True)
        self.assertEqual(actual.stdout.splitlines(), ['compose', 'ps', '-q', 'rdf4j'])

    def test_docker_wrapper_adds_writable_ci_bind_and_preserves_arguments(self):
        helper = ROOT / 'docker/ci-jvm-diagnostics.sh'
        self.assertTrue(helper.is_file())
        with tempfile.TemporaryDirectory() as temp:
            environment = dict(os.environ, RDF4J_JVM_DIAGNOSTICS_DIR=temp)
            script = 'source "$1"; docker() { printf "%s\\n" "$@"; printf "opts=%s\\n" "$RDF4J_DOCKER_JVM_DIAGNOSTIC_OPTIONS"; }; rdf4j_ci_docker_compose -f override.yml up -d'
            actual = subprocess.run(['bash', '-c', script, 'test', str(helper)], env=environment,
                                    capture_output=True, text=True, check=True)
            self.assertIn('docker-compose.jvm-diagnostics.yml', actual.stdout)
            self.assertIn('override.yml\nup\n-d\n', actual.stdout)
            self.assertIn('-XX:HeapDumpPath=/rdf4j-jvm-diagnostics/java_pid%p.hprof.gz', actual.stdout)
            self.assertTrue((Path(temp) / 'docker').is_dir())

if __name__ == '__main__':
    unittest.main()
